      "module": "./content/styles/layout.md.ts",
      "source": "const root = cdiv({ ui: [\"d-flex\", \"flex-col\", \"gap-2\"] });\nconst width = e(\"input\", { type: \"range\", min: \"280\", max: \"1200\", step: \"1\",\n    value: \"640\", ariaLabel: \"Container width\", ui: [\"min-w-0\", \"flex-1\"] });\nconst output = e(\"output\", { ui: [\"text-muted\"] });\nconst grid = e(\"div\", { ui: [\"grid\", \"gap-2\"], style: { width: \"640px\" } });\nconst field = (label, value) => e(\"label\", {\n    ui: [\"d-flex\", \"flex-col\", \"min-w-0\", \"col-12\", \"col-sm-6\", \"col-md-4\", \"col-lg-3\"]\n}, label, e(\"input\", { ui: [\"elg\", \"field\", \"min-w-0\"], value, ariaLabel: label }));\ngrid.append(field(\"Customer\", \"Northwind Office\"), field(\"Order number\", \"SO-1042\"), field(\"Date\", \"2026-10-13\"), field(\"Reference\", \"Website order\"), field(\"Currency\", \"EUR\"), field(\"Payment terms\", \"30 days\"), e(\"label\", { ui: [\"d-flex\", \"flex-col\", \"min-w-0\", \"col-12\", \"col-sm-6\", \"col-md-8\", \"col-lg-6\"] }, \"Address (larger span)\", e(\"input\", { ui: [\"elg\", \"field\", \"min-w-0\"], value: \"14 Market Street\", ariaLabel: \"Address\" })), e(\"label\", { ui: [\"d-flex\", \"flex-col\", \"min-w-0\", \"col-12\"] }, \"Notes (full row)\", e(\"textarea\", { ui: [\"elg\", \"field\", \"min-w-0\"], rows: 2, ariaLabel: \"Notes\" }, \"Deliver during office hours.\")));\nconst contact = cdiv({ ui: [\"elg\", \"surface-2\", \"p-2\", \"rounded-1\", \"col-12\", \"col-lg-6\"] }, e(\"strong\", {}, \"Contact — nested grid\"), e(\"div\", { ui: [\"grid\", \"gap-2\", \"mt-1\"] }, e(\"label\", { ui: [\"d-flex\", \"flex-col\", \"min-w-0\", \"col-12\", \"col-sm-6\"] }, \"Email\", e(\"input\", { ui: [\"elg\", \"field\", \"min-w-0\"], value: \"sales@example.com\", ariaLabel: \"Email\" })), e(\"label\", { ui: [\"d-flex\", \"flex-col\", \"min-w-0\", \"col-12\", \"col-sm-6\"] }, \"Phone\", e(\"input\", { ui: [\"elg\", \"field\", \"min-w-0\"], value: \"+359 2 123 4567\", ariaLabel: \"Phone\" }))));\ncontact.mount(grid);\nconst totals = cdiv({ ui: [\"col-12\", \"col-lg-6\"] });\ntotals.append(e(\"div\", { vnodes: [v(\"div\", { ui: [\"grid\", \"gap-2\"] }, v(\"div\", { ui: [\"elg\", \"surface-2\", \"p-2\", \"rounded-1\", \"col-12\", \"col-sm-6\"] }, \"Subtotal: €420\"), v(\"div\", { ui: [\"elg\", \"surface-2\", \"p-2\", \"rounded-1\", \"col-12\", \"col-sm-6\"] }, \"Total: €504\"))] }));\ntotals.mount(grid);\nfunction update() {\n    grid.style.width = width.value + \"px\";\n    const size = Number(width.value);\n    const mode = size >= 1024 ? \"lg: 4 fields / row\" : size >= 768 ? \"md: 3 fields / row\"\n        : size >= 480 ? \"sm: 2 fields / row\" : \"base: 1 field / row\";\n    output.textContent = size + \"px — \" + mode;\n}\nroot.listen(width, \"input\", update);\nconst presets = [360, 480, 768, 1024].map(size => e(\"button\", {\n    ui: [\"elg\", \"btn\", \"neutral\"], type: \"button\", onclick: () => {\n        width.value = String(size);\n        update();\n    }\n}, size + \"px\"));\nroot.append([\n    e(\"label\", { ui: [\"d-flex\", \"items-center\", \"gap-2\"] }, \"Container width\", width),\n    e(\"div\", { ui: [\"d-flex\", \"flex-wrap\", \"gap-1\", \"items-center\"] }, ...presets, output),\n    e(\"div\", { ui: [\"overflow-auto\", \"min-w-0\", \"p-1\"], style: { maxHeight: \"540px\" } }, grid)\n]);\nroot.mount(document.body);\nroot.addCleanup(() => { contact.dispose(); totals.dispose(); });\nupdate();",
